descriptor.templateCss:
* { box-sizing: border-box; }

.cd-widget {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    max-height: 100%;
    font-family: 'Roboto', sans-serif;
    background: #ffffff;
    padding: 8px 10px;
    overflow: hidden;
}

.cd-title {
    font-family: 'Roboto', sans-serif;
    font-size: 15px;
    font-weight: 500;
    line-height: 20px;
    color: rgba(0, 0, 0, 0.87);
    flex: 0 0 auto;
    padding-bottom: 4px;
}

/* max-height es un TOPE, no un tamaño fijo (igual que en el widget de
   "hoy"): con pocas filas la leyenda ocupa solo lo que necesita y el
   resto de alto disponible se lo queda la gráfica. El tope está
   calculado para que quepan SIN scroll la cabecera + la línea de fórmula
   + las 4 filas fijas (Caudal, Caudal Medio, Caudal Guarda, Caudal
   Manual) + hasta 3 caudalímetros individuales -- con un grupo de más
   caudalímetros que eso sí entra el scroll interno de la leyenda, pero
   nunca con 1, 2 o 3. */
.cd-legend-panel {
    flex: 0 0 auto;
    max-height: 195px;
    overflow-y: auto;
    padding-bottom: 2px;
    border-bottom: 1px solid rgba(0, 0, 0, 0.12);
    margin-bottom: 4px;
}

.cd-legend-header {
    display: flex;
    align-items: baseline;
    gap: 10px;
    font-size: 10px;
    line-height: 1.2;
    color: rgba(0, 0, 0, 0.54);
    padding-bottom: 3px;
    width: fit-content;
}
.cd-legend-header-spacer { flex: 0 0 8px; }
.cd-legend-header-name { flex: 0 0 170px; }
.cd-legend-header-col { flex: 0 0 82px; text-align: right; white-space: nowrap; padding-right: 10px; }
/* Columnas "Caudal actual" y "Volumen total": en negrita y con más
   tamaño que el resto de cabeceras, para que destaquen de un vistazo
   -- igual que en el widget de "hoy". */
.cd-legend-header-destacado { font-weight: 700; font-size: 12px; color: rgba(0, 0, 0, 0.72); }

.cd-legend-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 1px 0;
    width: fit-content;
    cursor: default;
}
.cd-legend-row.cd-legend-clickable { cursor: pointer; }
.cd-legend-row.cd-legend-off { opacity: 0.35; }

.cd-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex: 0 0 8px;
}
/* Punto de leyenda para la serie "Caudal Medio": se dibuja como un
   trazo discontinuo (en vez de circulo solido) para que, de un
   vistazo, se vea que esa es la linea discontinua de la grafica. */
.cd-dot-discontinuo {
    width: 10px;
    height: 0;
    border-radius: 0;
    border-top: 2px dashed currentColor;
    background: none;
    flex: 0 0 10px;
}

.cd-legend-name {
    flex: 0 0 170px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 400;
    line-height: 16px;
    color: rgba(0, 0, 0, 0.76);
}

.cd-legend-val {
    flex: 0 0 82px;
    text-align: right;
    padding-right: 10px;
    font-variant-numeric: tabular-nums;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 500;
    line-height: 16px;
    color: rgba(0, 0, 0, 0.76);
}

.cd-chart-panel {
    flex: 1 1 auto;
    min-height: 0;
    position: relative;
    min-width: 0;
    /* Fix: dejamos hueco a la derecha para que la etiqueta del ultimo punto
       de "Caudal Medio" (p.ej. "5 L/s") no quede cortada por el
       overflow:hidden del widget cuando el punto cae pegado al borde. */
    padding-right: 42px;
}

#cd-svg {
    display: block;
    overflow: visible;
}

.cd-tooltip {
    position: absolute;
    display: none;
    pointer-events: none;
    background: rgba(255,255,255,0.96);
    border: 1px solid rgba(0,0,0,0.12);
    border-radius: 4px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    padding: 6px 10px;
    font-size: 12px;
    color: rgba(0,0,0,0.76);
    white-space: nowrap;
    z-index: 20;
}
.cd-tooltip-row { display: flex; align-items: center; gap: 6px; }
.cd-tooltip-dot { width: 7px; height: 7px; border-radius: 50%; flex: 0 0 7px; }
.cd-tooltip-time { font-weight: 500; margin-bottom: 3px; color: rgba(0,0,0,0.87); }

/* ---- Edicion de signo (+Suma/-Resta) por caudalimetro, para dias
   pasados. Mismo estilo que los botones del widget "Caudalimetros del
   grupo" en vivo, para que se reconozcan como la misma accion. ---- */
.cd-signo-botones {
    display: flex;
    gap: 4px;
    flex: 0 0 auto;
    margin-left: 4px;
}
.cd-btn-signo {
    font-family: 'Roboto', sans-serif;
    font-size: 11px;
    font-weight: 600;
    border: none;
    border-radius: 4px;
    padding: 3px 8px;
    cursor: pointer;
    color: #ffffff;
    opacity: 0.35;
    transition: opacity 0.12s ease;
}
.cd-btn-signo:hover { opacity: 0.6; }
.cd-btn-signo.cd-btn-signo-activo { opacity: 1; }
.cd-btn-signo.cd-btn-signo-activo:hover { opacity: 1; }
.cd-btn-suma { background: #1976d2; }
.cd-btn-resta { background: #d32f2f; }

/* ---- Aviso "cambios sin guardar" + boton "Guardar cambios" ---- */
.cd-aviso-guardar {
    display: none;
    flex: 0 0 auto;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    background: #fff8e1;
    border: 1px solid #ffca28;
    border-radius: 4px;
    padding: 6px 10px;
    margin-bottom: 6px;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    color: rgba(0, 0, 0, 0.76);
}
.cd-btn-guardar {
    flex: 0 0 auto;
    font-family: 'Roboto', sans-serif;
    font-size: 12px;
    font-weight: 700;
    border: none;
    border-radius: 4px;
    padding: 6px 14px;
    cursor: pointer;
    background: #2e7d32;
    color: #ffffff;
}
.cd-btn-guardar:hover { background: #256428; }
.cd-btn-guardar:disabled { opacity: 0.6; cursor: default; }

/* ============================================================
   NUEVO: corregir el valor de un caudalímetro en un instante concreto
   de un día pasado, haciendo clic sobre un punto de la gráfica. Mismos
   estilos que el modal equivalente del widget de "día actual"
   (comparativa_caudales_FIX.js / .cc-overlay-editar / .cc-modal-editar),
   con el prefijo "cd-" para no chocar con el otro widget.
   ============================================================ */
.cd-overlay-editar {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000000;
}
.cd-modal-editar {
    background: #ffffff;
    border-radius: 8px;
    padding: 22px 24px 18px;
    width: 320px;
    max-width: 90vw;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
    font-family: 'Roboto', sans-serif;
}
.cd-modal-titulo {
    font-size: 17px;
    font-weight: 700;
    color: rgba(0, 0, 0, 0.87);
    margin-bottom: 2px;
}
.cd-modal-sub {
    font-size: 13px;
    color: rgba(0, 0, 0, 0.54);
    margin-bottom: 10px;
}
.cd-modal-actual {
    font-size: 13px;
    color: rgba(0, 0, 0, 0.7);
    margin-bottom: 10px;
}
.cd-modal-label {
    display: block;
    font-size: 12px;
    font-weight: 600;
    color: rgba(0, 0, 0, 0.6);
    margin-bottom: 4px;
}
.cd-modal-select {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid rgba(0, 0, 0, 0.28);
    border-radius: 4px;
    padding: 7px 8px;
    font-family: inherit;
    font-size: 13px;
    color: rgba(0, 0, 0, 0.87);
    margin-bottom: 10px;
    background: #ffffff;
}
.cd-modal-nota {
    font-size: 12px;
    color: rgba(0, 0, 0, 0.6);
    margin-top: 8px;
    min-height: 16px;
}
.cd-modal-input {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid rgba(0, 0, 0, 0.28);
    border-radius: 4px;
    padding: 8px 10px;
    font-family: inherit;
    font-size: 14px;
    color: rgba(0, 0, 0, 0.87);
    outline: none;
    transition: border-color 0.15s ease;
}
.cd-modal-input:focus { border-color: #1976d2; }
.cd-modal-botones {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 16px;
}
.cd-modal-btn {
    padding: 8px 18px;
    border-radius: 4px;
    border: none;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}
.cd-modal-btn-cancelar { background: #eceff1; color: #37474f; }
.cd-modal-btn-cancelar:hover { background: #dfe4e8; }
.cd-modal-btn-guardar { background: #1976d2; color: #ffffff; }
.cd-modal-btn-guardar:hover { background: #1662ab; }
.cd-modal-btn-guardar:disabled { opacity: 0.6; cursor: default; }

descriptor.controllerScript:
// ============================================================
// REGISTRO DE CAMBIOS (lo lee el widget de Auditoría)
// Cada vez que este widget cambia un valor, guarda en la entidad una
// telemetría "registro_cambio" con quién lo cambió, el valor ANTERIOR y el
// NUEVO. La Auditoría lee solo esta clave, así que no le afectan los
// recálculos internos (volumen, media proyectada, reescritura del día...).
// ============================================================
var CLAVE_REGISTRO_CAMBIO = 'registro_cambio';
var ultimoTsRegistro = 0;
function usuarioActual(ctx) {
    var u = (ctx && ctx.currentUser) || {};
    if (u.sub || u.email) return u.sub || u.email;
    try {
        var jwt = localStorage.getItem('jwt_token');
        if (jwt) {
            var b64 = jwt.split('.')[1].replace(/-/g, '+').replace(/_/g, '/');
            var datos = JSON.parse(decodeURIComponent(escape(atob(b64))));
            return datos.sub || datos.email || '';
        }
    } catch (e) {}
    return '';
}
// cambios: [{ tipo: 'punto'|'media', clave, ts, anterior, nuevo }]
// Los que no cambian de verdad (anterior === nuevo) se descartan solos.
function registrarCambio(ctx, entityType, entityId, cambios) {
    var reales = (cambios || []).map(function (c) {
        var copia = {};
        for (var k in c) { if (c.hasOwnProperty(k)) copia[k] = c[k]; }
        copia.anterior = (c.anterior === null || c.anterior === undefined || isNaN(parseFloat(c.anterior))) ? null : parseFloat(c.anterior);
        copia.nuevo = parseFloat(c.nuevo);
        return copia;
    }).filter(function (c) {
        return !isNaN(c.nuevo) && c.anterior !== c.nuevo;
    });
    if (!reales.length || !entityId) return;
    var ts = Date.now();
    if (ts <= ultimoTsRegistro) ts = ultimoTsRegistro + 1;   // dos registros seguidos no se pisan
    ultimoTsRegistro = ts;
    var payload = { ts: ts, values: {} };
    payload.values[CLAVE_REGISTRO_CAMBIO] = JSON.stringify({ usuario: usuarioActual(ctx), cambios: reales });
    try {
        ctx.http.post('/api/plugins/telemetry/' + (entityType || 'ASSET') + '/' + entityId + '/timeseries/ANY', payload)
            .subscribe(function () {}, function (err) {
                console.error('[registro_cambio] no se pudo guardar el registro del cambio', err);
            });
    } catch (e) {
        console.error('[registro_cambio] excepción al guardar el registro del cambio', e);
    }
}

// ============================================================
// Colores y etiquetas EXACTOS del widget nativo "Comparativa caudales"
// (version DIAS ANTERIORES). Al entrar al widget solo se ven "Caudal"
// (caudal_Sum) y "Caudal Medio" (caudal_fijado) -- el resto (Caudal
// Manual, Caudal Guarda y cada caudalímetro individual) arranca oculto,
// igual que en el widget de hoy; el usuario los puede mostrar haciendo
// clic en su nombre en la leyenda.
//
// ============================================================
// CAMBIOS DE ESTA VERSION (arreglo de "a veces no cambia" + linea
// discontinua invisible):
//
// 1) (Version 2, superada por el punto 2 de abajo) -- primero se cambio el
//    "espia" de localStorage.riego_ts_ir_ayer de solo-lectura a activo, en
//    cada tick. Pero se comprobo en pruebas reales que ese flag ya NO es
//    de fiar para este widget (ver punto 2) -- se ha sustituido del todo.
//
// 2) VERSION 3 -- el widget "Selector de fecha" (sf.js) ha pasado a ser el
//    dueño real de la navegacion entre dias: el decide el dia y llama a
//    dashboard.onUpdateTimewindow(); el flag riego_ts_ir_ayer YA NO es una
//    fuente fiable para cd.js (sf.js lo consume y lo borra en su propio
//    onInit). Por eso cd.js ha dejado de depender de ese flag: ahora
//    vigila $ctx.timeWindow.minTime directamente -- la misma fuente que ya
//    usan con exito "Selector de fecha" y "Guardar Caudal Manual" -- y en
//    cuanto cambia, pide ella misma por HTTP los datos de ese dia, sin
//    esperar a que la suscripcion de ThingsBoard se enganche a tiempo.
//
// 3) "Caudal Medio" (caudal_fijado) normalmente solo trae UN punto (el
//    cierre del dia a las 23:59) -- una <polyline> con un solo punto no
//    dibuja ningun segmento, asi que la linea discontinua no se veia
//    NUNCA, aunque el dato estuviera perfectamente bien. Ahora, si la
//    serie "media" solo tiene un punto, se le añade automaticamente un
//    segundo punto sintetico a las 00:00 del dia con el MISMO valor, asi
//    se dibuja un segmento discontinuo visible a lo largo del dia.
//
// 4) Logs mucho mas claros, todos con marca de tiempo real (hora:min:seg.ms)
//    ademas del INSTANCE_ID, en cada paso clave: zombie-check (con motivo),
//    lectura del flag, dia pedido vs. dia confirmado, arranque/fin del
//    fetch manual, numero de puntos por serie antes y despues de pintar.
//
// 5) Se añade la unidad "L/s" a la etiqueta numerica que acompaña al final
//    de la linea discontinua de "Caudal Medio" (antes solo mostraba el
//    numero), igual que ya se hizo en el widget de "hoy".
//
// 6) NUEVO -- EDICION DE SIGNO POR CAUDALIMETRO EN DIAS PASADOS. Cada
//    caudalímetro individual de la leyenda ahora lleva sus propios botones
//    "+ Suma" / "− Resta" (igual que en el widget "Caudalímetros del
//    grupo" en vivo), pero aplicados al DIA que se esta viendo en este
//    widget, no al presente. Al hacer clic:
//      a) La linea de ESE caudalimetro se invierte al momento en la
//         grafica (solo visualmente, la lectura cruda nunca se toca).
//      b) "Caudal" (caudal_Sum) y "Caudal Medio" (caudal_fijado) se
//         recalculan tambien al momento, en el navegador, como VISTA
//         PREVIA de lo que quedaria guardado.
//      c) Aparece un aviso de "cambios sin guardar" con un boton
//         "Guardar cambios". Al guardar, se reescribe DE VERDAD (sincrono,
//         antes de dar por guardado) la telemetria derivada del
//         Grupo_Riego para ese dia (caudal_Sum, caudal_total_diario_m3,
//         caudal_fijado), se desplaza el acumulado anual/historico
//         (caudal_total_anual_m3 / caudal_total_m3) desde ese dia hasta
//         hoy por el volumen exacto que cambia de signo, y se guarda el
//         signo corregido de ese dia en el atributo
//         operaciones_caudalimetros_historico del Grupo_Riego -- SIN
//         tocar jamas la lectura cruda `caudal` del caudalimetro.
//      d) Estos calculos replican EXACTAMENTE las formulas de la cadena de
//         reglas Pila_de_Datos_v2.3 ("Decodificar y acumular", "Calcular
//         caudal fijado (incremental)"): vol = caudal * dtSeg/1000 por
//         intervalo, y caudal_fijado = media ponderada por tiempo.
//
// 7) NUEVO -- selector +Suma/-Resta restringido a los grupos que de
//    verdad combinan caudalímetros en producción (Bujalmoro, La Española,
//    La Algabarrilla) -- ver GRUPOS_CON_SIGNO/grupoPermiteSigno más abajo.
//    En el resto de grupos no se muestran los botones, aunque tengan más
//    de un caudalímetro, para evitar cambios accidentales de signo donde
//    no se ha pedido esta opción.
// ============================================================
var INSTANCE_ID = 'cd#' + Math.random().toString(36).slice(2, 7);

function horaLog() {
    var d = new Date();
    function pad(n, len) { return n.toString().padStart(len || 2, '0'); }
    return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()) + '.' + pad(d.getMilliseconds(), 3);
}
function log() {
    var args = Array.prototype.slice.call(arguments);
    args.unshift('[' + horaLog() + '][' + INSTANCE_ID + ']');
    console.log.apply(console, args);
}
function logWarn() {
    var args = Array.prototype.slice.call(arguments);
    args.unshift('[' + horaLog() + '][' + INSTANCE_ID + ']');
    console.warn.apply(console, args);
}
function logError() {
    var args = Array.prototype.slice.call(arguments);
    args.unshift('[' + horaLog() + '][' + INSTANCE_ID + ']');
    console.error.apply(console, args);
}

log('[INSTANCIA] nueva instancia de cd.js creada');

// ============================================================
var SERIES_FIJAS = {
    // "Caudal" y "Caudal Medio" (caudal_fijado) comparten el MISMO azul --
    // igual que en el widget de hoy, lo que las distingue ya no es el color
    // sino el trazo (discontinuo solo para "Caudal Medio", ver esSerieMedia
    // y el punto de leyenda "cd-dot-discontinuo").
    'caudal_Sum':     { label: 'Caudal',        color: '#0288D1', mostrarEnLeyenda: true },
    'caudal_manual':  { label: 'Caudal Manual', color: '#F49836', mostrarEnLeyenda: true },
    'caudal_fijado':  { label: 'Caudal Medio',  color: '#0288D1', mostrarEnLeyenda: true },
    'caudal_guarda':  { label: 'Caudal Guarda', color: '#9c27b0', mostrarEnLeyenda: true }
};
// Series visibles al arrancar el widget: el resto (Caudal Manual, Caudal
// Guarda y cada caudalímetro individual) empieza OCULTO, como si se
// hubiera hecho clic en su nombre en la leyenda -- el usuario los puede
// volver a mostrar haciendo clic, igual que siempre.
var SERIES_VISIBLES_POR_DEFECTO = { 'caudal_Sum': true, 'caudal_fijado': true };
var COLOR_ENTIDAD_DEFECTO = '#f44336';
var CLAVE_ENTIDAD_LINEA = 'caudal';              // se dibuja, no aporta numero a la leyenda
var CLAVE_ENTIDAD_NUMERO = 'caudal_medio_diario'; // no se dibuja, solo aporta el numero "Caudal actual"
var CLAVE_VOLUMEN = 'caudal_total_diario_m3';
// Cada punto de caudal_manual representa un intervalo de 15 minutos (900
// segundos): L/s * 900 s = litros de ESE intervalo, /1000 = m³. Se usa para
// calcular a mano el "Volumen total" de Caudal Manual (no existe esa
// telemetría) -- misma conversión que en el widget de hoy.
var INTERVALO_MINUTOS = 15;
var FACTOR_VOLUMEN_INTERVALO = INTERVALO_MINUTOS * 60 / 1000; // = 0.9 con 15 min
var EXPLICACIONES = {
    'caudal_Sum': 'Caudal instantáneo total de ese día: suma en tiempo real del caudal de los caudalímetros, medida a lo largo del día (no es una media).',
    'caudal_manual': 'Caudal introducido a mano cuando no hubo lectura automática fiable ese día.',
    'caudal_fijado': 'Caudal medio: media real de todo el día, calculada al cierre (23:59h). Es un valor cerrado, no una estimación.',
    'caudal_guarda': 'Caudal reportado por el guarda de la zona ese día.'
};
var EXPLICACION_ENTIDAD = 'Media real de este caudalímetro para todo el día (calculada al cierre). La línea de la gráfica muestra la lectura cruda; este número es la media cerrada del día.';
var EXPLICACION_VOLUMEN = 'Volumen total acumulado ese día (m³).';
var SVG_NS = 'http://www.w3.org/2000/svg';
var MARGEN = { top: 10, right: 16, bottom: 26, left: 44 };
var ultimoDataset = null;
// "Caudal Medio" es la unica serie que representa una MEDIA/agregado
// cerrado del dia (no una lectura directa) -- por eso es la unica que se
// dibuja con linea discontinua y lleva la etiqueta numerica al final.
function esSerieMedia(id) {
    return id === 'caudal_fijado';
}
// NUEVO: el selector +Suma/-Resta solo tiene sentido (y solo se debe poder
// tocar) en los 3 grupos que de verdad combinan varios caudalímetros en
// producción -- en el resto de grupos se quita por completo, aunque ese
// grupo tenga más de un caudalímetro, para evitar cambios accidentales de
// signo en grupos donde no se ha pedido esta opción.
var GRUPOS_CON_SIGNO = ['Bujalmoro', 'La Española', 'La Algabarrilla'];
function normalizarNombreGrupo(s) {
    return (s || '').toString().toLowerCase()
        .normalize('NFD').replace(/[̀-ͯ]/g, '')
        .replace(/[^a-z0-9]/g, '');
}
var GRUPOS_CON_SIGNO_NORM = GRUPOS_CON_SIGNO.map(normalizarNombreGrupo);
function grupoPermiteSigno(nombreGrupo) {
    return GRUPOS_CON_SIGNO_NORM.indexOf(normalizarNombreGrupo(nombreGrupo)) !== -1;
}
function idDeDatasource(ds) {
    if (!ds) return null;
    return ds.entityId || (ds.entity && ds.entity.id && ds.entity.id.id) || ds.name || null;
}
// Igual que idDeDatasource, pero ademas del id devuelve el entityType (ASSET,
// DEVICE...), que hace falta para poder pedir telemetria a mano via HTTP
// (ver fetchManualYPintar). Si no se encuentra un entityType explicito, se
// asume 'ASSET' -- todas las entidades que usa este widget (Grupo_Riego y
// los caudalimetros) lo son.
function entityRefDeDatasource(ds) {
    if (!ds) return null;
    var id = ds.entityId || (ds.entity && ds.entity.id && ds.entity.id.id) || null;
    if (!id) return null;
    var type = ds.entityType || (ds.entity && ds.entity.id && ds.entity.id.entityType) || 'ASSET';
    return { id: id, type: type };
}
// ============================================================
// Series ocultas por el usuario (clic en la leyenda) -- se guarda por
// "id" de serie, y se mantiene aunque lleguen datos nuevos (no se
// resetea con cada actualización). SERIES_VISIBLES_POR_DEFECTO decide el
// estado inicial la PRIMERA vez que se ve cada id; a partir de ahí el
// usuario manda con sus clics.
// ============================================================
var seriesOcultas = {};
var defaultsAplicados = {};
function asegurarEstadoPorDefecto(id) {
    if (defaultsAplicados[id]) { return; }
    defaultsAplicados[id] = true;
    if (!SERIES_VISIBLES_POR_DEFECTO[id]) {
        seriesOcultas[id] = true;
    }
}

// ============================================================
// NUEVO -- EDICION DE SIGNO POR CAUDALIMETRO / DIA
// ============================================================
// Clave del dia que se esta viendo, en formato "YYYY-MM-DD" (fecha LOCAL
// del navegador, igual convencion que el resto del fichero: inicioDiaLey/
// finDiaLey se calculan con new Date(...).getFullYear()/getMonth()/getDate()
// locales, no en UTC -- se usa la misma aqui para que la clave del dia
// coincida siempre con el dia que realmente se esta pintando).
function claveDia(ts) {
    var d = new Date(ts);
    function p2(n) { return (n < 10 ? '0' : '') + n; }
    return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate());
}

var ATRIBUTO_HISTORICO = 'operaciones_caudalimetros_historico';
// Snapshot crudo (sin firmar) de lo ultimo recibido por suscripcion/fetch,
// para poder recalcular la vista previa sin volver a pedir nada al
// servidor cada vez que el usuario le da a +Suma/-Resta.
var estadoCrudo = null; // { entityIdBase, entityRefBase, entityNombreBase, inicioDia, finDia, fechaStr, seriesFijas:{}, volumenTotalBase, entidades:{} }
// Signo elegido en la pantalla ahora mismo, por caudalimetro (entityId):
// 'suma' | 'resta'. Se inicializa con lo que ya hay guardado para este dia
// (o 'suma' por defecto si no hay nada guardado, igual que la cadena de
// reglas).
var signosDia = {};
// Snapshot de signosDia justo cuando se cargo el dia (o justo despues del
// ultimo guardado) -- sirve para (a) saber si hay cambios sin guardar, y
// (b) saber el "signo antiguo" real que hay que pasarle al motor de
// recalculo al guardar.
var signosOriginales = {};
var guardando = false;
var fechaStrCargada = null; // dia para el que estan cargados signosDia/signosOriginales

function hayCambiosSinGuardar() {
    var ids = Object.keys(signosDia);
    for (var i = 0; i < ids.length; i++) {
        if (signosDia[ids[i]] !== signosOriginales[ids[i]]) return true;
    }
    return false;
}

// Lee (o inicializa) los signos guardados para el dia actual, a partir del
// atributo operaciones_caudalimetros_historico del Grupo_Riego. No falla
// nunca de forma visible: si no hay nada guardado, todos arrancan en
// 'suma' (igual que el valor por defecto real de la cadena de reglas
// cuando un caudalimetro no tiene signo configurado).
function cargarSignosDelDia($ctx, entityRefBase, fechaStr, nombresPorEntidad) {
    var url = '/api/plugins/telemetry/' + entityRefBase.type + '/' + entityRefBase.id +
        '/values/attributes/SERVER_SCOPE?keys=' + ATRIBUTO_HISTORICO;
    return $ctx.http.get(url).toPromise().then(function (resp) {
        var mapaDia = {};
        try {
            if (resp && resp.length && resp[0] && resp[0].value) {
                var historicoCompleto = JSON.parse(resp[0].value);
                mapaDia = historicoCompleto[fechaStr] || {};
            }
        } catch (e) {
            logWarn('[signos] operaciones_caudalimetros_historico mal formado, se ignora:', e);
        }
        var nuevo = {};
        Object.keys(nombresPorEntidad).forEach(function (entityId) {
            var nombre = nombresPorEntidad[entityId];
            nuevo[entityId] = (mapaDia[nombre] === 'resta') ? 'resta' : 'suma';
        });
        return nuevo;
    }).catch(function (err) {
        logError('[signos] no se pudo leer ' + ATRIBUTO_HISTORICO + ':', err);
        var nuevo = {};
        Object.keys(nombresPorEntidad).forEach(function (entityId) { nuevo[entityId] = 'suma'; });
        return nuevo;
    });
}

/* ---- Formulas replicadas EXACTAMENTE de Pila_de_Datos_v2.3, para la
 * vista previa en el navegador y para el guardado real. ---- */
var MAX_DT_S = 3600;
function r3(x) { return Math.round(x * 1000) / 1000; }

// Reintegra el volumen acumulado DENTRO DEL DIA de un caudalimetro, punto
// a punto, a partir de su serie cruda `caudal` (nunca se modifica esa
// serie, solo se lee). vol = caudal_actual * dtSeg/1000, igual que
// "Decodificar y acumular".
function integrarVolumenDia(lecturasDelDia, ultimaLecturaAntesDelDia) {
    var acumulado = 0;
    var tsPrevio = ultimaLecturaAntesDelDia ? ultimaLecturaAntesDelDia.x : null;
    var serie = []; // [{ts, caudal, acumuladoDia}]
    lecturasDelDia.forEach(function (p) {
        var caudal = isNaN(p.y) ? 0 : p.y;
        var dtSeg = 0;
        if (tsPrevio !== null) {
            dtSeg = (p.x - tsPrevio) / 1000;
            if (dtSeg < 0) dtSeg = 0;
            if (dtSeg > MAX_DT_S) dtSeg = MAX_DT_S;
        }
        acumulado = r3(acumulado + caudal * dtSeg / 1000);
        serie.push({ ts: p.x, caudal: caudal, acumuladoDia: acumulado });
        tsPrevio = p.x;
    });
    return serie;
}

// Media ponderada por tiempo de una serie {ts,value} dentro de [inicioDia,
// finDia], cerrando el ultimo tramo hasta finDia -- igual que "Calcular
// caudal fijado (incremental)".
function mediaPonderadaPorTiempo(serie, inicioDia, finDia) {
    if (!serie.length) return null;
    var sumaPonderada = 0, tiempoAcumulado = 0;
    var tsPrevio = inicioDia, valorPrevio = serie[0].value;
    serie.forEach(function (p) {
        var gap = Math.max(0, p.ts - tsPrevio);
        sumaPonderada += valorPrevio * gap;
        tiempoAcumulado += gap;
        tsPrevio = p.ts;
        valorPrevio = p.value;
    });
    var gapCierre = Math.max(0, finDia - tsPrevio);
    sumaPonderada += valorPrevio * gapCierre;
    tiempoAcumulado += gapCierre;
    if (tiempoAcumulado <= 0) return null;
    return Math.round((sumaPonderada / tiempoAcumulado) * 100) / 100;
}

self.onInit = function() {
    // Vacio a proposito: la logica de "aplicar dia anterior" se ha movido a
    // onDataUpdated (y ahora tambien al polling activo, ver
    // iniciarPollingFlag), porque onInit NO es fiable aqui -- si el
    // dialogo reutiliza el mismo componente entre aperturas (pasa en
    // ThingsBoard con "abrir en dialogo separado"), onInit solo se
    // ejecuta la primera vez.
    log('onInit() llamado');
};

var ultimoMinTimeAplicado = null;

function leerDiaDesdeFuenteMasFiable() {
    try {
        var raw = localStorage.getItem('riego_dia_actual');
        if (raw) {
            var datos = JSON.parse(raw);
            if (datos && typeof datos.ts === 'number') {
                return { ts: datos.ts, origen: 'riego_dia_actual' };
            }
        }
    } catch (e) {
        logWarn('[dia] riego_dia_actual mal formado, se ignora:', e);
    }
    var mt = self.ctx.timeWindow && self.ctx.timeWindow.minTime;
    if (typeof mt === 'number') {
        return { ts: mt, origen: 'timeWindow.minTime (respaldo)' };
    }
    return null;
}

var ultimasFuentes = null;
var peticionFetchActual = 0;

function guardarFuentesConocidas(data) {
    var fuentes = [];
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        var ref = entityRefDeDatasource(item.datasource);
        if (!keyName || !ref) return;
        fuentes.push({ keyName: keyName, entityRef: ref, datasource: item.datasource });
    });
    if (fuentes.length > 0) { ultimasFuentes = fuentes; }
}

function fetchManualYPintar(startTs, endTs) {
    if (!ultimasFuentes || ultimasFuentes.length === 0) {
        logWarn('[fetch manual] todavia no se conocen las entidades/keys del widget -- no se puede pedir el dia a mano.');
        return;
    }
    var porEntidad = {};
    ultimasFuentes.forEach(function(f) {
        var clave = f.entityRef.type + ':' + f.entityRef.id;
        if (!porEntidad[clave]) { porEntidad[clave] = { ref: f.entityRef, keys: [], datasourcePorKey: {} }; }
        if (porEntidad[clave].keys.indexOf(f.keyName) === -1) { porEntidad[clave].keys.push(f.keyName); }
        porEntidad[clave].datasourcePorKey[f.keyName] = f.datasource;
    });
    var claves = Object.keys(porEntidad);
    if (claves.length === 0) return;
    var miPeticion = ++peticionFetchActual;
    var pendientes = claves.length;
    var huboError = false;
    var dataSintetica = [];
    log('[fetch manual] #' + miPeticion + ' pidiendo a mano ' + claves.length + ' entidad(es) para ' + new Date(startTs).toString() + ' .. ' + new Date(endTs).toString());
    claves.forEach(function(clave) {
        var info = porEntidad[clave];
        var url = '/api/plugins/telemetry/' + info.ref.type + '/' + info.ref.id +
            '/values/timeseries?keys=' + info.keys.join(',') + '&startTs=' + startTs + '&endTs=' + endTs + '&limit=2000';
        self.ctx.http.get(url).subscribe(function(resp) {
            if (miPeticion !== peticionFetchActual) { log('[fetch manual] #' + miPeticion + ' respuesta descartada (ya hay una peticion mas nueva #' + peticionFetchActual + ')'); return; }
            info.keys.forEach(function(k) {
                var puntos = (resp && resp[k] ? resp[k] : []).map(function(p) { return [p.ts, p.value]; });
                dataSintetica.push({ dataKey: { name: k }, datasource: info.datasourcePorKey[k], data: puntos });
            });
            pendientes--;
            if (pendientes === 0) {
                if (huboError) { logWarn('[fetch manual] #' + miPeticion + ' alguna entidad fallo, se pinta con lo que se pudo conseguir.'); }
                log('[fetch manual] #' + miPeticion + ' todas las respuestas llegaron (' + dataSintetica.length + ' series) -- pintando directamente.');
                procesarDatosYActualizar(dataSintetica);
            }
        }, function(err) {
            if (miPeticion !== peticionFetchActual) return;
            huboError = true;
            pendientes--;
            logError('[fetch manual] #' + miPeticion + ' error pidiendo telemetria de ' + clave + ':', err);
            if (pendientes === 0 && dataSintetica.length > 0) { procesarDatosYActualizar(dataSintetica); }
        });
    });
}

function estoyVivoYVisibleDetalle() {
    var $miPanel = $(self.ctx.$container).closest('.cdk-overlay-pane');
    if ($miPanel.length > 0 && $miPanel.attr('data-iay-oculto') === '1') {
        return { vivo: false, motivo: 'panel marcado data-iay-oculto=1' };
    }
    var contenedor = self.ctx.$container && self.ctx.$container.get ? self.ctx.$container.get(0) : null;
    if (!contenedor) {
        return { vivo: false, motivo: 'self.ctx.$container.get(0) no devuelve nada' };
    }
    if (!document.body.contains(contenedor)) {
        return { vivo: false, motivo: 'contenedor desconectado de document.body' };
    }
    return { vivo: true, motivo: null };
}
function estoyVivoYVisible() {
    return estoyVivoYVisibleDetalle().vivo;
}

var pollingIniciado = false;
var pollingIntervalId = null;

function revisarCambioDeDia() {
    if (!estoyVivoYVisible()) return false;
    var fuente = leerDiaDesdeFuenteMasFiable();
    if (!fuente) return false;
    var mt = fuente.ts;
    if (mt === ultimoMinTimeAplicado) return false;
    var esPrimeraVez = (ultimoMinTimeAplicado === null);
    log('[dia] (fuente: ' + fuente.origen + ') ' + (esPrimeraVez ? 'dia detectado' : 'dia CAMBIA') + ': ' +
        ultimoMinTimeAplicado + ' -> ' + mt + ' (' + new Date(mt).toString() + ')');
    ultimoMinTimeAplicado = mt;
    // El dia ha cambiado: cualquier cambio de signo sin guardar del dia
    // anterior deja de tener sentido en pantalla (no se pierde nada real
    // porque nunca se llego a persistir) -- se limpia el estado para que
    // el aviso de "cambios sin guardar" no se quede pegado al cambiar de dia.
    signosDia = {};
    signosOriginales = {};
    fechaStrCargada = null;
    var fechaRef = new Date(mt);
    var inicioDia = new Date(fechaRef.getFullYear(), fechaRef.getMonth(), fechaRef.getDate(), 0, 0, 0).getTime();
    var finDia = inicioDia + 24 * 60 * 60 * 1000 - 1;
    if (!ultimasFuentes || ultimasFuentes.length === 0) {
        log('[dia] todavia no se conocen las entidades/keys del widget -- se pintara en cuanto llegue el primer onDataUpdated con datos.');
        return true;
    }
    fetchManualYPintar(inicioDia, finDia);
    return true;
}

function iniciarPolling() {
    if (pollingIniciado) return;
    pollingIniciado = true;
    log('[POLLING] arrancando vigilancia de timeWindow.minTime cada 300ms');
    pollingIntervalId = setInterval(function() {
        var detalle = estoyVivoYVisibleDetalle();
        if (!detalle.vivo) {
            log('[POLLING] esta instancia ya no esta viva/visible (' + detalle.motivo + ') -- parando el polling.');
            clearInterval(pollingIntervalId);
            return;
        }
        revisarCambioDeDia();
    }, 300);
}

self.onDataUpdated = function() {
    var detalleVivo = estoyVivoYVisibleDetalle();
    if (!detalleVivo.vivo) {
        log('onDataUpdated LLAMADO pero descartado (' + detalleVivo.motivo + ')');
        return;
    }
    iniciarPolling();
    var $ctx = self.ctx;
    var data = $ctx.data || [];
    guardarFuentesConocidas(data);
    log('onDataUpdated -- timeWindow.minTime=' + ($ctx.timeWindow && $ctx.timeWindow.minTime) +
        ' (' + ($ctx.timeWindow && $ctx.timeWindow.minTime ? new Date($ctx.timeWindow.minTime).toString() : '?') + ')' +
        ' -- series recibidas: ' + data.length +
        ' -- primer punto: ' + JSON.stringify((data[0] && data[0].data && data[0].data[0]) || null));
    var diaAcabaDeCambiar = revisarCambioDeDia();
    if (diaAcabaDeCambiar) {
        log('onDataUpdated -- se omite pintar con el "data" de este tick porque el dia acaba de cambiar (se pintara con la respuesta del fetch manual).');
        return;
    }
    procesarDatosYActualizar(data);
};

// Cuerpo de "procesar los datos y pintar". Ahora en dos fases: primero se
// guarda todo lo CRUDO (sin firmar) en estadoCrudo, y luego
// aplicarSignosYReconstruir() construye lo que se dibuja de verdad a
// partir de ese crudo + signosDia -- asi, cuando el usuario le da a
// +Suma/-Resta, no hace falta volver a pedir nada al servidor: solo se
// vuelve a llamar a aplicarSignosYReconstruir().
function procesarDatosYActualizar(data) {
    var $ctx = self.ctx;
    log('procesarDatosYActualizar() -- ' + data.length + ' series recibidas');
    var inicioDiaLey = null, finDiaLey = null;
    var fuenteDiaLey = leerDiaDesdeFuenteMasFiable();
    if (fuenteDiaLey) {
        var fechaRefLey = new Date(fuenteDiaLey.ts);
        inicioDiaLey = new Date(fechaRefLey.getFullYear(), fechaRefLey.getMonth(), fechaRefLey.getDate(), 0, 0, 0).getTime();
        finDiaLey = inicioDiaLey + 24 * 60 * 60 * 1000;
    }
    function ultimoDelDia(arrRaw) {
        var filtrado = (inicioDiaLey === null)
            ? arrRaw
            : arrRaw.filter(function(p) { return p[0] >= inicioDiaLey && p[0] < finDiaLey; });
        if (filtrado.length === 0) return null;
        var mejor = filtrado[0];
        filtrado.forEach(function(p) { if (p[0] > mejor[0]) { mejor = p; } });
        return parseFloat(mejor[1]);
    }
    // ---- PASO 1: entidad BASE (STATE, el Grupo_Riego) ----
    var entityIdBase = null;
    var entityRefBase = null;
    var entityNombreBase = null;
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        if (entityIdBase) return;
        if (SERIES_FIJAS.hasOwnProperty(keyName)) {
            entityIdBase = idDeDatasource(item.datasource);
            entityRefBase = entityRefDeDatasource(item.datasource);
            entityNombreBase = (item.datasource && (item.datasource.entityLabel || item.datasource.entityName)) || null;
        }
    });
    // ---- PASO 2: series fijas + volumen total (SOLO de la entidad base) ----
    var seriesFijasRaw = {}; // { caudal_Sum: [{x,y}], caudal_fijado: [...], ... }
    var volumenTotalBase = null;
    var volumenManualCalculado = null;
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        var esDeLaBase = idDeDatasource(item.datasource) === entityIdBase;
        if (keyName === CLAVE_VOLUMEN && esDeLaBase) {
            volumenTotalBase = ultimoDelDia(item.data || []);
            return;
        }
        if (!SERIES_FIJAS.hasOwnProperty(keyName) || !esDeLaBase) return;
        var puntos = (item.data || []).map(function(p) { return { x: p[0], y: parseFloat(p[1]) }; }).sort(function(a, b) { return a.x - b.x; });
        seriesFijasRaw[keyName] = puntos;
        if (keyName === 'caudal_manual') {
            var rawManual = item.data || [];
            var filtradoManual = (inicioDiaLey === null) ? rawManual : rawManual.filter(function(p) { return p[0] >= inicioDiaLey && p[0] < finDiaLey; });
            if (filtradoManual.length > 0) {
                var sumaM3 = 0;
                filtradoManual.forEach(function(p) { var v = parseFloat(p[1]); if (!isNaN(v)) { sumaM3 += v * FACTOR_VOLUMEN_INTERVALO; } });
                volumenManualCalculado = Math.round(sumaM3 * 100) / 100;
            }
        }
    });
    // ---- PASO 3: series por entidad (caudalímetros) -- EXCLUYENDO la entidad base ----
    var entidadesRaw = {}; // { entityId: { nombre, entityRef, lineaPuntos, mediaDiaria, volumenUltimo } }
    data.forEach(function(item) {
        var keyName = item.dataKey && item.dataKey.name;
        if (keyName !== CLAVE_ENTIDAD_LINEA && keyName !== CLAVE_ENTIDAD_NUMERO && keyName !== CLAVE_VOLUMEN) return;
        var entityId = idDeDatasource(item.datasource);
        if (!entityId || entityId === entityIdBase) return;
        if (!entidadesRaw[entityId]) {
            entidadesRaw[entityId] = {
                nombre: item.datasource.entityLabel || item.datasource.entityName || entityId,
                entityRef: entityRefDeDatasource(item.datasource),
                lineaPuntos: [],
                mediaDiaria: null,
                volumenUltimo: null
            };
        }
        if (keyName === CLAVE_ENTIDAD_LINEA) {
            entidadesRaw[entityId].lineaPuntos = (item.data || []).map(function(p) { return { x: p[0], y: parseFloat(p[1]) }; }).sort(function(a, b) { return a.x - b.x; });
            if (item.dataKey.label && item.dataKey.label !== '${entityLabel}') {
                entidadesRaw[entityId].nombre = item.dataKey.label;
            }
        } else if (keyName === CLAVE_ENTIDAD_NUMERO) {
            entidadesRaw[entityId].mediaDiaria = ultimoDelDia(item.data || []);
        } else {
            entidadesRaw[entityId].volumenUltimo = ultimoDelDia(item.data || []);
        }
    });

    estadoCrudo = {
        entityIdBase: entityIdBase,
        entityRefBase: entityRefBase,
        entityNombreBase: entityNombreBase,
        inicioDia: inicioDiaLey,
        finDia: finDiaLey,
        seriesFijasRaw: seriesFijasRaw,
        volumenTotalBase: volumenTotalBase,
        volumenManualCalculado: volumenManualCalculado,
        entidades: entidadesRaw
    };

    var fechaStr = (inicioDiaLey !== null) ? claveDia(inicioDiaLey) : null;
    if (!fechaStr || !entityRefBase) {
        // No hay suficiente informacion todavia (primer tick) -- se pinta
        // igualmente sin signos editables, se completara en cuanto llegue.
        aplicarSignosYReconstruir();
        return;
    }
    if (fechaStrCargada === fechaStr) {
        // Mismo dia que ya teniamos cargado (p.ej. llega una actualizacion
        // periodica de la suscripcion): no se pisan los signos que el
        // usuario pueda tener elegidos sin guardar todavia.
        aplicarSignosYReconstruir();
        return;
    }
    var nombresPorEntidad = {};
    Object.keys(entidadesRaw).forEach(function(id) { nombresPorEntidad[id] = entidadesRaw[id].nombre; });
    cargarSignosDelDia($ctx, entityRefBase, fechaStr, nombresPorEntidad).then(function(signos) {
        fechaStrCargada = fechaStr;
        signosDia = signos;
        signosOriginales = JSON.parse(JSON.stringify(signos));
        aplicarSignosYReconstruir();
    });
}

// Reconstruye "datasets" (lo que se dibuja) y "filasLeyenda" a partir de
// estadoCrudo + signosDia -- sin pedir nada al servidor. Esta es la
// funcion que se vuelve a llamar cada vez que el usuario cambia un signo.
function aplicarSignosYReconstruir() {
    if (!estadoCrudo) return;
    var inicioDiaLey = estadoCrudo.inicioDia;
    var finDiaLey = estadoCrudo.finDia;
    var datasets = [];
    var filasLeyenda = [];

    function signoNum(entityId) { return (signosDia[entityId] === 'resta') ? -1 : 1; }
    function signoOriginalNum(entityId) { return (signosOriginales[entityId] === 'resta') ? -1 : 1; }

    // ---- Delta a aplicar sobre "Caudal" (caudal_Sum) en cada instante t:
    // suma, para cada caudalimetro cuyo signo se haya tocado en pantalla,
    // de (signoNuevo - signoOriginal) * lectura_cruda_del_caudalimetro(t).
    // Es EXACTAMENTE la misma formula que usa el motor de guardado real.
    function deltaCaudalSumEnT(t) {
        var delta = 0;
        Object.keys(estadoCrudo.entidades).forEach(function(entityId) {
            var deltaSigno = signoNum(entityId) - signoOriginalNum(entityId);
            if (deltaSigno === 0) return;
            var info = estadoCrudo.entidades[entityId];
            var val = 0;
            for (var i = 0; i < info.lineaPuntos.length; i++) {
                if (info.lineaPuntos[i].x <= t) { val = isNaN(info.lineaPuntos[i].y) ? 0 : info.lineaPuntos[i].y; }
                else break;
            }
            delta += deltaSigno * val;
        });
        return delta;
    }

    // ---- "Caudal" (caudal_Sum): serie real + delta de vista previa ----
    var caudalSumRaw = estadoCrudo.seriesFijasRaw['caudal_Sum'] || [];
    var caudalSumPreview = caudalSumRaw.map(function(p) {
        return { x: p.x, y: r3(p.y + deltaCaudalSumEnT(p.x)) };
    });
    if (SERIES_FIJAS['caudal_Sum']) {
        datasets.push({ id: 'caudal_Sum', label: SERIES_FIJAS['caudal_Sum'].label, color: SERIES_FIJAS['caudal_Sum'].color, puntos: caudalSumPreview });
        filasLeyenda.push({
            id: 'caudal_Sum', color: SERIES_FIJAS['caudal_Sum'].color, nombre: SERIES_FIJAS['caudal_Sum'].label,
            // La fila "Caudal" NO muestra ningun numero (antes salia el
            // ultimo valor del dia, que no aporta nada): solo sirve como
            // clave de color y para mostrar/ocultar su linea.
            caudalActual: null,
            volumenTotal: null,
            sinValores: true
        });
    }

    // ---- "Caudal Medio" (caudal_fijado): recalculado a partir del
    // caudal_Sum de vista previa si hay algun cambio de signo sin guardar;
    // si no hay ningun cambio, se deja tal cual vino del servidor (para no
    // introducir pequeñas diferencias de redondeo sin necesidad). ----
    var fijadoRaw = estadoCrudo.seriesFijasRaw['caudal_fijado'] || [];
    var hayCambios = hayCambiosSinGuardar();
    var fijadoPreviewPuntos = fijadoRaw;
    var volumenPreviewBase = estadoCrudo.volumenTotalBase;
    if (hayCambios && inicioDiaLey !== null && caudalSumPreview.length > 0) {
        var serieParaMedia = caudalSumPreview.map(function(p) { return { ts: p.x, value: p.y }; });
        var mediaPreview = mediaPonderadaPorTiempo(serieParaMedia, inicioDiaLey, finDiaLey);
        if (mediaPreview !== null) {
            fijadoPreviewPuntos = [{ x: inicioDiaLey, y: mediaPreview }, { x: finDiaLey - 1, y: mediaPreview }];
        }
        // Vista previa del volumen del dia (m3): se reintegra sumando el
        // volumen sin signo de cada caudalimetro tocado, con su signo nuevo.
        var deltaVolumenDia = 0;
        Object.keys(estadoCrudo.entidades).forEach(function(entityId) {
            var deltaSigno = signoNum(entityId) - signoOriginalNum(entityId);
            if (deltaSigno === 0) return;
            var info = estadoCrudo.entidades[entityId];
            var lecturasDelDia = info.lineaPuntos.filter(function(p) { return p.x >= inicioDiaLey && p.x < finDiaLey && !isNaN(p.y); });
            var serieAcum = integrarVolumenDia(lecturasDelDia, null);
            var volDia = serieAcum.length ? serieAcum[serieAcum.length - 1].acumuladoDia : 0;
            deltaVolumenDia += deltaSigno * volDia;
        });
        if (volumenPreviewBase !== null) { volumenPreviewBase = r3(volumenPreviewBase + deltaVolumenDia); }
    }
    // FIX (2026-10-06): el "Volumen total" del grupo es SIEMPRE la suma de
    // los volúmenes de sus caudalímetros (cada uno con el signo +/- que
    // tenga en pantalla), para que cuadre exactamente con las filas de
    // abajo. Antes se mostraba el último valor de "caudal_total_diario_m3"
    // del Grupo_Riego, que lo calcula el servidor por su cuenta y a veces
    // se queda desfasado (p.ej. Bujalmoro 05/10: 8.253 m³ frente a
    // 7.838 + 533 = 8.371 m³ de sus caudalímetros). Solo si ningún
    // caudalímetro tiene volumen se usa el valor del servidor.
    var sumaVolCaudalimetros = 0;
    var hayVolCaudalimetros = false;
    Object.keys(estadoCrudo.entidades).forEach(function(entityId) {
        var infoVol = estadoCrudo.entidades[entityId];
        if (infoVol.volumenUltimo === null || infoVol.volumenUltimo === undefined || isNaN(infoVol.volumenUltimo)) return;
        sumaVolCaudalimetros += signoNum(entityId) * infoVol.volumenUltimo;
        hayVolCaudalimetros = true;
    });
    // + ajustes por correcciones de picos de ese día (ver CLAVE_AJUSTE_VOLUMEN)
    asegurarAjustesVolumenDia();
    if (hayVolCaudalimetros) { volumenPreviewBase = r3(sumaVolCaudalimetros + sumaAjustesVolumenDia()); }
    if (SERIES_FIJAS['caudal_fijado']) {
        datasets.push({ id: 'caudal_fijado', label: SERIES_FIJAS['caudal_fijado'].label, color: SERIES_FIJAS['caudal_fijado'].color, puntos: fijadoPreviewPuntos });
        filasLeyenda.push({
            id: 'caudal_fijado', color: SERIES_FIJAS['caudal_fijado'].color, nombre: SERIES_FIJAS['caudal_fijado'].label,
            caudalActual: fijadoPreviewPuntos.length ? fijadoPreviewPuntos[fijadoPreviewPuntos.length - 1].y : null,
            volumenTotal: volumenPreviewBase
        });
    }

    // ---- Caudal Manual / Caudal Guarda: sin cambios, tal cual vinieron ----
    ['caudal_manual', 'caudal_guarda'].forEach(function(id) {
        var puntos = estadoCrudo.seriesFijasRaw[id];
        if (!puntos) return;
        var def = SERIES_FIJAS[id];
        datasets.push({ id: id, label: def.label, color: def.color, puntos: puntos });
        var ultimo = puntos.length ? (function() {
            var filtrado = (inicioDiaLey === null) ? puntos : puntos.filter(function(p) { return p.x >= inicioDiaLey && p.x < finDiaLey; });
            if (!filtrado.length) return null;
            var mejor = filtrado[0];
            filtrado.forEach(function(p) { if (p.x > mejor.x) mejor = p; });
            return mejor.y;
        })() : null;
        filasLeyenda.push({ id: id, color: def.color, nombre: def.label, caudalActual: ultimo, volumenTotal: (id === 'caudal_manual') ? estadoCrudo.volumenManualCalculado : null });
    });

    // ---- Caudalimetros individuales: linea y numeros con el signo ELEGIDO
    // en pantalla (aunque no se haya guardado todavia) -- asi se ve el
    // efecto al instante. ----
    // FIX (2026-10-06): los caudalimetros se pintan SIEMPRE ordenados por
    // toma (CAU-79-1, CAU-79-2, CAU-79-3, CAU-79-4...), no en el orden en
    // que llegan los datos del servidor, que puede variar.
    idsEntidadesOrdenados().forEach(function(entityId) {
        asegurarEstadoPorDefecto(entityId);
        var info = estadoCrudo.entidades[entityId];
        var signo = signoNum(entityId);
        var puntos = info.lineaPuntos.map(function(p) { return { x: p.x, y: isNaN(p.y) ? p.y : signo * p.y }; });
        datasets.push({ id: entityId, label: info.nombre, color: COLOR_ENTIDAD_DEFECTO, puntos: puntos });
        filasLeyenda.push({
            id: entityId, color: COLOR_ENTIDAD_DEFECTO, nombre: info.nombre,
            caudalActual: (info.mediaDiaria === null) ? null : signo * info.mediaDiaria,
            volumenTotal: (info.volumenUltimo === null) ? null : signo * info.volumenUltimo,
            esCaudalimetro: true,
            signo: signosDia[entityId] || 'suma'
        });
    });

    log('aplicarSignosYReconstruir() -- datasets: ' + datasets.map(function(d) { return d.id + '(' + d.puntos.length + 'pts)'; }).join(', ') + (hayCambios ? ' -- HAY CAMBIOS SIN GUARDAR' : ''));
    ultimoDataset = datasets;
    pintarLeyenda(self.ctx, filasLeyenda);
    pintarAvisoGuardar(self.ctx);
    requestAnimationFrame(function() {
        dibujarGrafico(self.ctx, datasets);
    });
}

// ============================================================
// FIX (2026-10-06): AJUSTES DE VOLUMEN POR CORRECCIÓN DE PICOS -- igual que
// en el widget de "día actual". El "Volumen total" del grupo es la suma de
// los volúmenes de sus caudalímetros MÁS los ajustes guardados al corregir
// picos de "Caudal" (clave "ajuste_volumen_correccion_m3" del Grupo_Riego,
// un punto por cada instante corregido, con los m³ que cambia el día).
// ============================================================
var CLAVE_AJUSTE_VOLUMEN = 'ajuste_volumen_correccion_m3';
var ajustesVolumenDia = { clave: null, cargando: false, mapa: {} }; // clave = "entityId|inicioDia"
function sumaAjustesVolumenDia() {
    var t = 0;
    for (var k in ajustesVolumenDia.mapa) { if (ajustesVolumenDia.mapa.hasOwnProperty(k)) { var v = parseFloat(ajustesVolumenDia.mapa[k]); if (!isNaN(v)) t += v; } }
    return t;
}
function asegurarAjustesVolumenDia() {
    if (!estadoCrudo || !estadoCrudo.entityRefBase || estadoCrudo.inicioDia === null || estadoCrudo.inicioDia === undefined) return;
    var clave = estadoCrudo.entityRefBase.id + '|' + estadoCrudo.inicioDia;
    if (ajustesVolumenDia.clave === clave || ajustesVolumenDia.cargando) return;
    ajustesVolumenDia.cargando = true;
    fetchSerieTs(self.ctx, estadoCrudo.entityRefBase, CLAVE_AJUSTE_VOLUMEN, estadoCrudo.inicioDia, estadoCrudo.finDia - 1).then(function(arr) {
        var mapa = {};
        arr.forEach(function(p) { mapa[p.ts] = parseFloat(p.value) || 0; });
        ajustesVolumenDia = { clave: clave, cargando: false, mapa: mapa };
        aplicarSignosYReconstruir();
    }).catch(function() {
        ajustesVolumenDia = { clave: clave, cargando: false, mapa: {} };
        aplicarSignosYReconstruir();
    });
}

// Ids de los caudalimetros del grupo ordenados por nombre de toma, con
// orden "natural" de los numeros (CAU-79-2 antes que CAU-79-10).
function idsEntidadesOrdenados() {
    if (!estadoCrudo || !estadoCrudo.entidades) return [];
    var colla = new Intl.Collator('es', { numeric: true, sensitivity: 'base' });
    return Object.keys(estadoCrudo.entidades).sort(function(a, b) {
        var na = (estadoCrudo.entidades[a] && estadoCrudo.entidades[a].nombre) || '';
        var nb = (estadoCrudo.entidades[b] && estadoCrudo.entidades[b].nombre) || '';
        var c = colla.compare(na, nb);
        return c !== 0 ? c : colla.compare(a, b);
    });
}

function fmt(n) {
    if (n === null || n === undefined || isNaN(n)) return '-';
    var redondeado = Math.round(n);
    var negativo = redondeado < 0;
    var texto = Math.abs(redondeado).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    return (negativo ? '-' : '') + texto;
}

function pintarLeyenda($ctx, filas) {
    var $lista = $ctx.$container.find('#cd-legend-list').empty();
    filas.forEach(function(f) {
        var explicacion = EXPLICACIONES.hasOwnProperty(f.id) ? EXPLICACIONES[f.id] : EXPLICACION_ENTIDAD;
        var tituloAttr = (f.nombre + ' — ' + explicacion).replace(/"/g, '&quot;');
        var tituloVolumen = (f.nombre + ' — ' + EXPLICACION_VOLUMEN).replace(/"/g, '&quot;');
        var oculto = !!seriesOcultas[f.id];
        var claseDot = esSerieMedia(f.id) ? 'cd-dot cd-dot-discontinuo' : 'cd-dot';
        var botonesHtml = '';
        // El selector +Suma/-Resta solo aparece si el grupo (entidad base)
        // es uno de los 3 autorizados (ver GRUPOS_CON_SIGNO) -- en el resto
        // de grupos esta opcion no debe poder tocarse.
        if (f.esCaudalimetro && grupoPermiteSigno(estadoCrudo && estadoCrudo.entityNombreBase)) {
            var activoSuma = f.signo !== 'resta';
            botonesHtml =
                '<span class="cd-signo-botones" data-entity-id="' + f.id + '">' +
                    '<button type="button" class="cd-btn-signo cd-btn-suma' + (activoSuma ? ' cd-btn-signo-activo' : '') + '" data-signo="suma">+ Suma</button>' +
                    '<button type="button" class="cd-btn-signo cd-btn-resta' + (!activoSuma ? ' cd-btn-signo-activo' : '') + '" data-signo="resta">− Resta</button>' +
                '</span>';
        }
        var $row = $(
            '<div class="cd-legend-row' + (f.esCaudalimetro ? '' : ' cd-legend-clickable') + (oculto ? ' cd-legend-off' : '') + '" data-serie-id="' + f.id + '"' + (f.esCaudalimetro ? '' : ' title="Clic para ' + (oculto ? 'mostrar' : 'ocultar') + ' esta línea"') + '>' +
                '<span class="' + claseDot + '" style="background:' + (esSerieMedia(f.id) ? 'none' : f.color) + ';color:' + f.color + '"></span>' +
                '<span class="cd-legend-name" title="' + tituloAttr + '">' + f.nombre + '</span>' +
                '<span class="cd-legend-val" title="' + tituloAttr + '">' + (f.sinValores ? '' : fmt(f.caudalActual) + ' L/s') + '</span>' +
                '<span class="cd-legend-val" title="' + tituloVolumen + '">' + (f.volumenTotal !== null ? fmt(f.volumenTotal) + ' m³' : '') + '</span>' +
                botonesHtml +
            '</div>'
        );
        $lista.append($row);
    });
    // Clic en el nombre/valor de una fila (no caudalimetro) sigue
    // ocultando/mostrando la linea, igual que siempre.
    $lista.find('.cd-legend-row.cd-legend-clickable').off('click').on('click', function() {
        var id = $(this).attr('data-serie-id');
        if (seriesOcultas[id]) { delete seriesOcultas[id]; } else { seriesOcultas[id] = true; }
        $(this).toggleClass('cd-legend-off', !!seriesOcultas[id]);
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
    });
    // Clic en el nombre de un caudalimetro tambien oculta/muestra su linea
    // (pero NO al pulsar los botones de signo -- se para la propagacion).
    $lista.find('.cd-legend-row').not('.cd-legend-clickable').on('click', function(evt) {
        if ($(evt.target).closest('.cd-signo-botones').length > 0) return;
        var id = $(this).attr('data-serie-id');
        if (seriesOcultas[id]) { delete seriesOcultas[id]; } else { seriesOcultas[id] = true; }
        $(this).toggleClass('cd-legend-off', !!seriesOcultas[id]);
        if (ultimoDataset) { dibujarGrafico($ctx, ultimoDataset); }
    });
    // Botones +Suma / -Resta: cambian el signo SOLO en pantalla (vista
    // previa) -- no llaman al servidor todavia, eso lo hace el boton
    // "Guardar cambios" (ver pintarAvisoGuardar / guardarCambiosDeSigno).
    $lista.find('.cd-btn-signo').off('click').on('click', function(evt) {
        evt.stopPropagation();
        if (guardando) return;
        var entityId = $(this).closest('.cd-signo-botones').attr('data-entity-id');
        var nuevoSigno = $(this).attr('data-signo');
        if (signosDia[entityId] === nuevoSigno) return;
        signosDia[entityId] = nuevoSigno;
        aplicarSignosYReconstruir();
    });
}

// Aviso de "cambios sin guardar" + boton "Guardar cambios", justo debajo
// de la cabecera de la leyenda. Se crea una vez y se muestra/oculta segun
// haga falta (no se reconstruye entero en cada repintado, para no perder
// el foco/estado del boton mientras se esta guardando).
function pintarAvisoGuardar($ctx) {
    var $panelLeyenda = $ctx.$container.find('.cd-legend-panel');
    var $aviso = $ctx.$container.find('#cd-aviso-guardar');
    if ($aviso.length === 0) {
        $aviso = $('<div id="cd-aviso-guardar" class="cd-aviso-guardar">' +
            '<span class="cd-aviso-texto">Hay cambios de signo sin guardar para este día.</span>' +
            '<button type="button" class="cd-btn-guardar">Guardar cambios</button>' +
        '</div>');
        $panelLeyenda.before($aviso);
        $aviso.find('.cd-btn-guardar').on('click', function() { guardarCambiosDeSigno($ctx); });
    }
    $aviso.toggle(hayCambiosSinGuardar() && !guardando);
}

/* ---------------------------------------------------------------------
 * GUARDADO REAL -- se ejecuta al pulsar "Guardar cambios". Reescribe,
 * de forma SINCRONA (se espera con await antes de dar nada por hecho),
 * la telemetria derivada del Grupo_Riego para el dia que se esta viendo,
 * y desplaza los acumulados anual/historico. Nunca toca la lectura cruda
 * `caudal` del caudalimetro.
 * ------------------------------------------------------------------- */
function fetchSerieTs($ctx, entityRef, key, startTs, endTs) {
    var url = '/api/plugins/telemetry/' + entityRef.type + '/' + entityRef.id + '/values/timeseries'
        + '?keys=' + key + '&startTs=' + startTs + '&endTs=' + endTs + '&limit=50000&orderBy=ASC';
    return $ctx.http.get(url).toPromise().then(function (data) {
        var arr = (data && data[key]) ? data[key].slice() : [];
        arr.sort(function (a, b) { return a.ts - b.ts; });
        return arr;
    });
}
function borrarSerieTs($ctx, entityRef, key, startTs, endTs) {
    var url = '/api/plugins/telemetry/' + entityRef.type + '/' + entityRef.id + '/timeseries/delete'
        + '?keys=' + key + '&startTs=' + startTs + '&endTs=' + endTs + '&deleteAllDataForKeys=false';
    return $ctx.http.delete(url).toPromise();
}
function postSerieTs($ctx, entityRef, key, puntos) {
    // Forma EXACTA ya probada y funcionando en produccion, copiada de
    // borrarYGuardar() dentro de abrirModalEdicion en
    // comparativa_caudales_FIX.js: el "ts" va DENTRO del body (NO como
    // query param), y el body es { ts, values: { clave: valor } } --
    // nunca { clave: valor } a secas ni ?ts=... en la URL.
    //
    // NUEVO -- antes se mandaban TODOS los puntos a la vez con
    // Promise.all, sin limite. En un dia con muchos puntos (caudal_Sum,
    // caudal_total_diario_m3...) eso son decenas de peticiones HTTP
    // disparadas en el mismo instante, y en pruebas reales del usuario a
    // veces saturaba la conexion/proxy y varias fallaban con
    // "net::ERR_FAILED" / "0 Unknown Error" a mitad de la operacion,
    // dejando el dia a medio corregir. Ahora se postea por LOTES
    // pequenos (como mucho CONCURRENCIA_MAX a la vez) y cada punto que
    // falla se reintenta un par de veces antes de dar el fallo por
    // bueno -- mas lento, pero mucho mas fiable.
    var url = '/api/plugins/telemetry/' + entityRef.type + '/' + entityRef.id + '/timeseries/ANY';
    var CONCURRENCIA_MAX = 4;
    var REINTENTOS_POR_PUNTO = 2;
    var ESPERA_ENTRE_REINTENTOS_MS = 400;
    function esperar(ms) { return new Promise(function (resolve) { setTimeout(resolve, ms); }); }
    function postUno(p, intentosRestantes) {
        var payload = { ts: p.ts, values: {} };
        payload.values[key] = p.value;
        return $ctx.http.post(url, payload).toPromise().catch(function (err) {
            if (intentosRestantes > 0) {
                logWarn('[postSerieTs] fallo posteando ' + key + ' en ts=' + p.ts + ', reintentando (' + intentosRestantes + ' intento(s) mas)...', err);
                return esperar(ESPERA_ENTRE_REINTENTOS_MS).then(function () { return postUno(p, intentosRestantes - 1); });
            }
            throw err;
        });
    }
    var idx = 0;
    function siguienteLote() {
        if (idx >= puntos.length) return Promise.resolve();
        var lote = puntos.slice(idx, idx + CONCURRENCIA_MAX);
        idx += lote.length;
        return Promise.all(lote.map(function (p) { return postUno(p, REINTENTOS_POR_PUNTO); })).then(siguienteLote);
    }
    return siguienteLote();
}

async function recalcularYGuardarDiaCorregido($ctx, params) {
    var grupoRef = params.grupoRef;
    var caudalimetroRef = params.caudalimetroRef;
    var caudalimetroNombre = params.caudalimetroNombre;
    var inicioTs = params.inicioTs;
    var finTs = params.finTs;
    var fechaStr = params.fechaStr;
    var signoAntiguo = params.signoAntiguo; // 1 o -1
    var signoNuevo = params.signoNuevo;     // 1 o -1

    if (signoAntiguo === signoNuevo) return;

    var lecturaAnteriorArr = await fetchSerieTs($ctx, caudalimetroRef, 'caudal', inicioTs - 6 * 3600000, inicioTs);
    var lecturaAnterior = lecturaAnteriorArr.length ? { x: lecturaAnteriorArr[lecturaAnteriorArr.length - 1].ts, y: parseFloat(lecturaAnteriorArr[lecturaAnteriorArr.length - 1].value) } : null;
    var lecturasRaw = await fetchSerieTs($ctx, caudalimetroRef, 'caudal', inicioTs, finTs);
    if (!lecturasRaw.length) {
        throw new Error('No hay lecturas de "' + caudalimetroNombre + '" el ' + fechaStr + ' -- no se puede recalcular.');
    }
    var lecturasDelDia = lecturasRaw.map(function (p) { return { x: p.ts, y: parseFloat(p.value) }; });

    var serieAcumDia = integrarVolumenDia(lecturasDelDia, lecturaAnterior);
    var volumenTotalDiaSinSigno = serieAcumDia.length ? serieAcumDia[serieAcumDia.length - 1].acumuladoDia : 0;
    var deltaSigno = signoNuevo - signoAntiguo;
    var deltaDiarioTotal = r3(deltaSigno * volumenTotalDiaSinSigno);

    function caudalEnT(t) {
        var val = lecturaAnterior ? lecturaAnterior.y : 0;
        for (var i = 0; i < lecturasDelDia.length; i++) { if (lecturasDelDia[i].x <= t) { val = lecturasDelDia[i].y; } else break; }
        return isNaN(val) ? 0 : val;
    }
    function acumuladoDiaEnT(t) {
        var val = 0;
        for (var i = 0; i < serieAcumDia.length; i++) { if (serieAcumDia[i].ts <= t) { val = serieAcumDia[i].acumuladoDia; } else break; }
        return val;
    }

    var serieSumGrupo = await fetchSerieTs($ctx, grupoRef, 'caudal_Sum', inicioTs, finTs);
    var serieSumCorregida = serieSumGrupo.map(function (p) {
        return { ts: p.ts, value: Math.max(0, r3((parseFloat(p.value) || 0) + deltaSigno * caudalEnT(p.ts))) };
    });

    var serieDiarioGrupo = await fetchSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', inicioTs, finTs);
    var serieDiarioCorregida = serieDiarioGrupo.map(function (p) {
        return { ts: p.ts, value: Math.max(0, r3((parseFloat(p.value) || 0) + deltaSigno * acumuladoDiaEnT(p.ts))) };
    });

    var nuevoFijado = null;
    if (serieSumCorregida.length) {
        nuevoFijado = mediaPonderadaPorTiempo(serieSumCorregida.map(function (p) { return { ts: p.ts, value: p.value }; }), inicioTs, finTs);
    }
    // OJO: el punto de cierre va exactamente en "finTs" (el ultimo ms real
    // del dia), NO en "finTs - 1". Antes se restaba 1ms de mas por error, lo
    // que dejaba nuestro propio punto de cierre un instante ANTES que el
    // punto de cierre original del sistema -- si el borrado de abajo no
    // llegaba a barrer ese punto original (ver comentario siguiente), el
    // original quedaba con una marca de tiempo mas tardia y "ganaba" en
    // cualquier sitio que coja "el ultimo punto del dia" (como el
    // Calendario), haciendo parecer que la correccion no habia servido de
    // nada.
    var serieFijadoCorregida = (nuevoFijado !== null) ? [{ ts: inicioTs, value: nuevoFijado }, { ts: finTs, value: nuevoFijado }] : [];

    // Margen de seguridad al borrar (igual que ya se hace en otras partes
    // de este proyecto, ver calcularRangoDia en comparativa_caudales_FIX.js):
    // si la API trata "endTs" como un limite EXCLUSIVO (no incluido), un
    // borrado que terminase justo en "finTs" (el ultimo ms del dia) podria
    // dejar sin borrar el punto de cierre que el sistema escribe justo a
    // esa hora -- de ahi el "+5000" de margen, para barrer con holgura
    // cualquier punto que caiga justo en el borde del dia.
    var finTsBorrado = finTs + 5000;
    await borrarSerieTs($ctx, grupoRef, 'caudal_Sum', inicioTs, finTsBorrado);
    await borrarSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', inicioTs, finTsBorrado);
    await borrarSerieTs($ctx, grupoRef, 'caudal_fijado', inicioTs, finTsBorrado);
    if (serieSumCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_Sum', serieSumCorregida);
    if (serieDiarioCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', serieDiarioCorregida);
    if (serieFijadoCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_fijado', serieFijadoCorregida);

    if (deltaDiarioTotal !== 0) {
        var ahoraTs = new Date().getTime();
        var claves = ['caudal_total_anual_m3', 'caudal_total_m3'];
        for (var k = 0; k < claves.length; k++) {
            var key = claves[k];
            var serieFutura = await fetchSerieTs($ctx, grupoRef, key, finTs + 1, ahoraTs);
            if (!serieFutura.length) continue;
            var serieFuturaCorregida = serieFutura.map(function (p) { return { ts: p.ts, value: Math.max(0, r3((parseFloat(p.value) || 0) + deltaDiarioTotal)) }; });
            await borrarSerieTs($ctx, grupoRef, key, finTs + 1, ahoraTs);
            await postSerieTs($ctx, grupoRef, key, serieFuturaCorregida);
        }
    }

    // Guardar el signo corregido en el historico (merge, sin pisar otros
    // dias/caudalimetros ya guardados).
    var urlAttr = '/api/plugins/telemetry/' + grupoRef.type + '/' + grupoRef.id + '/values/attributes/SERVER_SCOPE?keys=' + ATRIBUTO_HISTORICO;
    var actual = await $ctx.http.get(urlAttr).toPromise();
    var historico = {};
    try { if (actual && actual.length && actual[0].value) { historico = JSON.parse(actual[0].value); } } catch (e) { historico = {}; }
    if (!historico[fechaStr]) historico[fechaStr] = {};
    historico[fechaStr][caudalimetroNombre] = (signoNuevo === -1) ? 'resta' : 'suma';
    await $ctx.http.post('/api/plugins/telemetry/' + grupoRef.type + '/' + grupoRef.id + '/SERVER_SCOPE', { operaciones_caudalimetros_historico: JSON.stringify(historico) }).toPromise();
}

/* ---------------------------------------------------------------------
 * NUEVO -- EDICION DE UN PUNTO CONCRETO EN UN DIA PASADO.
 *
 * Igual que en el widget de "día actual" (abrirModalEdicion en
 * comparativa_caudales_FIX.js), al hacer clic en un punto de la gráfica
 * se puede corregir el valor de UN caudalímetro en ESE instante exacto
 * -- por ejemplo, si ayer no dio tiempo a revisar la gráfica de hoy y se
 * quiere arreglar un pico raro al día siguiente.
 *
 * La diferencia con el widget de "día actual" es que aquí "Caudal"
 * (caudal_Sum), "Caudal Medio" (caudal_fijado) y el volumen del día
 * (caudal_total_diario_m3) son series YA CERRADAS que hay que
 * RECALCULAR de verdad (igual que ya hace recalcularYGuardarDiaCorregido
 * para un cambio de signo de todo el día), no basta con desplazar un
 * único punto suelto:
 *   - "Caudal" (caudal_Sum) se desplaza SOLO en el tramo de tiempo en el
 *     que ese caudalímetro mantenía la lectura que se está corrigiendo
 *     (desde el punto editado hasta el siguiente punto real de ese
 *     caudalímetro ese día) -- igual que "aguanta" su valor la cadena de
 *     reglas entre dos lecturas.
 *   - "caudal_total_diario_m3" (volumen acumulado del día) se desplaza
 *     desde el punto editado hasta el FINAL del día (es acumulado, el
 *     cambio arrastra al resto de la jornada).
 *   - "Caudal Medio" (caudal_fijado) se recalcula desde cero con la
 *     media ponderada por tiempo del "Caudal" ya corregido.
 *   - El acumulado anual/histórico (caudal_total_anual_m3 /
 *     caudal_total_m3) se desplaza desde el día corregido hasta hoy,
 *     por el volumen exacto que cambia -- igual que en un cambio de
 *     signo.
 *   - El signo (+Suma/-Resta) de ese caudalímetro para ese día NO se
 *     toca -- si estaba en "Resta", un aumento de su lectura cruda
 *     hace que "Caudal" del grupo BAJE, y así se calcula aquí.
 * ------------------------------------------------------------------- */

// Busca, dentro de una lista de puntos {x,y}, el más cercano en el
// tiempo a un ts dado (misma idea que puntoMasCercano en
// comparativa_caudales_FIX.js, adaptada al formato {x,y} de este fichero).
function puntoMasCercano(puntos, ts, margenMs) {
    var cercano = null, mejorDist = Infinity;
    (puntos || []).forEach(function (p) {
        if (isNaN(p.y)) return;
        var d = Math.abs(p.x - ts);
        if (d < mejorDist) { mejorDist = d; cercano = p; }
    });
    if (!cercano || (margenMs !== undefined && mejorDist > margenMs)) return null;
    return cercano;
}

// Busca, dentro de una serie {ts,value} (tal cual la devuelve
// fetchSerieTs), el punto más cercano en el tiempo a un ts dado -- misma
// idea que puntoMasCercano, adaptada al formato {ts,value}.
function puntoMasCercanoTs(serie, ts, margenMs) {
    var cercano = null, mejorDist = Infinity;
    (serie || []).forEach(function (p) {
        var v = parseFloat(p.value);
        if (isNaN(v)) return;
        var d = Math.abs(p.ts - ts);
        if (d < mejorDist) { mejorDist = d; cercano = p; }
    });
    if (!cercano || (margenMs !== undefined && mejorDist > margenMs)) return null;
    return cercano;
}

// Recalcula y guarda de verdad la corrección de UN pico de "Caudal"
// (caudal_Sum) DEL PROPIO GRUPO, para el día que se está viendo -- NO se
// toca ninguna lectura cruda de ningún caudalímetro, igual que en el
// widget de "día actual" (ver abrirModalEdicion en
// comparativa_caudales_FIX.js): el valor del caudalímetro que pudiera
// haber originado el pico es irrelevante para este ajuste, lo que hay
// que corregir es el dato ya combinado del grupo.
// params: { grupoRef, inicioTs, finTs, tsObjetivo, nuevoValor }
//
// Igual que corregirPuntoDiaPasado (la versión anterior, por
// caudalímetro), esto NO aplica un delta sobre lo que hubiera guardado
// antes -- "Caudal", el volumen del día y "Caudal Medio" se RECALCULAN
// ENTEROS a partir de la serie de "Caudal" YA CORREGIDA, así que repetir
// la misma corrección dos veces da siempre el mismo resultado
// (idempotente, nunca se suma de más).
async function corregirPicoCaudalSumDiaPasado($ctx, params) {
    var grupoRef = params.grupoRef;
    var inicioTs = params.inicioTs;
    var finTs = params.finTs;
    var tsObjetivo = params.tsObjetivo;
    var nuevoValor = params.nuevoValor;

    var serieSumOriginal = await fetchSerieTs($ctx, grupoRef, 'caudal_Sum', inicioTs, finTs);
    if (!serieSumOriginal.length) {
        throw new Error('No hay datos de "Caudal" ese día -- no se puede corregir.');
    }
    var puntoOriginal = puntoMasCercanoTs(serieSumOriginal, tsObjetivo, 30 * 60 * 1000);
    if (!puntoOriginal) {
        throw new Error('"Caudal" no tiene ningún dato cerca de esa hora -- no se puede corregir.');
    }

    // ---- "Caudal" (caudal_Sum) corregido: se sustituye SOLO el punto
    // elegido, el resto de la serie se deja tal cual. ----
    var serieSumCorregida = serieSumOriginal.map(function (p) {
        var valor = (p.ts === puntoOriginal.ts) ? nuevoValor : (parseFloat(p.value) || 0);
        return { ts: p.ts, value: Math.max(0, r3(valor)) };
    });

    // ---- Volumen del día (caudal_total_diario_m3): se reintegra
    // DIRECTAMENTE a partir de la serie de "Caudal" ya corregida -- misma
    // fórmula (vol = caudal * dtSeg/1000 por intervalo) que usa
    // integrarVolumenDia para un caudalímetro, aplicada aquí al propio
    // "Caudal" del grupo, evaluada en las mismas marcas de tiempo que ya
    // tenía guardadas la serie de volumen. ----
    var lecturaAnteriorArr = await fetchSerieTs($ctx, grupoRef, 'caudal_Sum', inicioTs - 6 * 3600000, inicioTs);
    var lecturaAnterior = lecturaAnteriorArr.length ? { x: inicioTs - 1, y: parseFloat(lecturaAnteriorArr[lecturaAnteriorArr.length - 1].value) } : null;
    var lecturasSumCorregidasXY = serieSumCorregida.map(function (p) { return { x: p.ts, y: p.value }; });
    var serieAcumDia = integrarVolumenDia(lecturasSumCorregidasXY, lecturaAnterior);
    function acumuladoEnT(t) {
        var val = 0;
        for (var j = 0; j < serieAcumDia.length; j++) { if (serieAcumDia[j].ts <= t) { val = serieAcumDia[j].acumuladoDia; } else break; }
        return val;
    }
    var serieDiarioGrupoOriginal = await fetchSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', inicioTs, finTs);
    var serieDiarioCorregida = serieDiarioGrupoOriginal.map(function (p) {
        return { ts: p.ts, value: Math.max(0, r3(acumuladoEnT(p.ts))) };
    });

    // ---- "Caudal Medio" (caudal_fijado): recalculado desde cero con la
    // media ponderada por tiempo del "Caudal" ya corregido. ----
    var nuevoFijado = serieSumCorregida.length
        ? mediaPonderadaPorTiempo(serieSumCorregida.map(function (p) { return { ts: p.ts, value: p.value }; }), inicioTs, finTs)
        : null;
    var serieFijadoCorregida = (nuevoFijado !== null) ? [{ ts: inicioTs, value: nuevoFijado }, { ts: finTs, value: nuevoFijado }] : [];

    // Cuánto cambia el volumen TOTAL del día (para desplazar el
    // acumulado anual/histórico): diferencia entre el volumen ya
    // recalculado y el que tenía guardado el grupo antes de tocar nada.
    // FIX (2026-10-06): el cambio de volumen se calcula integrando la serie
    // de "Caudal" ANTES y DESPUÉS de la corrección (misma fórmula), no
    // restando el volumen guardado en el grupo, que la cadena de reglas
    // reescribe con cada trama y no es fiable.
    var lecturasSumOriginalesXY = serieSumOriginal.map(function (p) { return { x: p.ts, y: parseFloat(p.value) || 0 }; });
    var serieAcumOriginal = integrarVolumenDia(lecturasSumOriginalesXY, lecturaAnterior);
    var volIntegradoAntes = serieAcumOriginal.length ? serieAcumOriginal[serieAcumOriginal.length - 1].acumuladoDia : 0;
    var volIntegradoDespues = serieAcumDia.length ? serieAcumDia[serieAcumDia.length - 1].acumuladoDia : 0;
    var deltaDiarioTotal = r3(volIntegradoDespues - volIntegradoAntes);

    var finTsBorrado = finTs + 5000;
    await borrarSerieTs($ctx, grupoRef, 'caudal_Sum', inicioTs, finTsBorrado);
    await borrarSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', inicioTs, finTsBorrado);
    await borrarSerieTs($ctx, grupoRef, 'caudal_fijado', inicioTs, finTsBorrado);
    if (serieSumCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_Sum', serieSumCorregida);
    if (serieDiarioCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_total_diario_m3', serieDiarioCorregida);
    if (serieFijadoCorregida.length) await postSerieTs($ctx, grupoRef, 'caudal_fijado', serieFijadoCorregida);

    // ---- Ajuste de volumen de esta corrección (ver CLAVE_AJUSTE_VOLUMEN):
    // se acumula sobre el que ya hubiera en ese mismo instante. ----
    if (deltaDiarioTotal !== 0) {
        var ajustesPrevios = await fetchSerieTs($ctx, grupoRef, CLAVE_AJUSTE_VOLUMEN, puntoOriginal.ts - 1, puntoOriginal.ts + 1);
        var ajustePrevio = ajustesPrevios.length ? (parseFloat(ajustesPrevios[ajustesPrevios.length - 1].value) || 0) : 0;
        await borrarSerieTs($ctx, grupoRef, CLAVE_AJUSTE_VOLUMEN, puntoOriginal.ts - 1, puntoOriginal.ts + 1);
        await postSerieTs($ctx, grupoRef, CLAVE_AJUSTE_VOLUMEN, [{ ts: puntoOriginal.ts, value: r3(ajustePrevio + deltaDiarioTotal) }]);
    }

    // ---- Desplazar el acumulado anual/histórico desde el día corregido
    // hasta hoy, por el volumen exacto que cambia. ----
    if (deltaDiarioTotal !== 0) {
        var ahoraTs = new Date().getTime();
        var claves = ['caudal_total_anual_m3', 'caudal_total_m3'];
        for (var k = 0; k < claves.length; k++) {
            var key = claves[k];
            var serieFutura = await fetchSerieTs($ctx, grupoRef, key, finTs + 1, ahoraTs);
            if (!serieFutura.length) continue;
            var serieFuturaCorregida = serieFutura.map(function (p) { return { ts: p.ts, value: Math.max(0, r3((parseFloat(p.value) || 0) + deltaDiarioTotal)) }; });
            await borrarSerieTs($ctx, grupoRef, key, finTs + 1, ahoraTs);
            await postSerieTs($ctx, grupoRef, key, serieFuturaCorregida);
        }
    }

    // Para el registro de cambios: el punto que se ha corregido de verdad,
    // con el valor que tenía en el servidor ANTES de reescribir el día.
    return {
        ts: puntoOriginal.ts,
        anterior: parseFloat(puntoOriginal.value),
        nuevo: Math.max(0, r3(nuevoValor))
    };
}

// Ventana modal: clic en un punto de la gráfica -> corregir DIRECTAMENTE
// el valor de "Caudal" (caudal_Sum) DEL GRUPO en ese instante, para el
// día que se está viendo -- ya NO se elige ningún caudalímetro ni se
// toca su lectura cruda (igual que abrirModalEdicion en
// comparativa_caudales_FIX.js para "día actual"). Llama a
// corregirPicoCaudalSumDiaPasado(), que recalcula entero "Caudal",
// "Caudal Medio" y el volumen del día a partir del "Caudal" corregido.
function abrirModalEdicionPicoGrupo($ctx, tsObjetivo) {
    if (!estadoCrudo || !estadoCrudo.entityRefBase) return;
    if (hayCambiosSinGuardar()) { alert('Hay cambios de signo sin guardar en este día. Guárdalos o descártalos (recargando) antes de corregir un pico.'); return; }
    if (guardando) return;
    $ctx.$container.find('.cd-overlay-editar').remove();
    var fecha = new Date(tsObjetivo);
    var fechaStr = fecha.toLocaleDateString('es-ES') + ' ' + fecha.toLocaleTimeString('es-ES', { hour: '2-digit', minute: '2-digit' });
    var $overlay = $(
        '<div class="cd-overlay-editar">' +
            '<div class="cd-modal-editar">' +
                '<div class="cd-modal-titulo">Corregir Caudal</div>' +
                '<div class="cd-modal-sub">' + fechaStr + '</div>' +
                '<div class="cd-modal-actual"></div>' +
                '<label class="cd-modal-label">Nuevo valor (L/s)</label>' +
                '<input type="number" class="cd-modal-input" step="any" placeholder="Nuevo valor (L/s)">' +
                '<div class="cd-modal-nota"></div>' +
                '<div class="cd-modal-botones">' +
                    '<button type="button" class="cd-modal-btn cd-modal-btn-cancelar">Cancelar</button>' +
                    '<button type="button" class="cd-modal-btn cd-modal-btn-guardar">Guardar</button>' +
                '</div>' +
            '</div>' +
        '</div>'
    );
    $ctx.$container.append($overlay);
    var $actual = $overlay.find('.cd-modal-actual');
    var $input = $overlay.find('.cd-modal-input');
    var $nota = $overlay.find('.cd-modal-nota');
    var datasetCaudalSum = null;
    (ultimoDataset || []).forEach(function (ds) { if (ds.id === 'caudal_Sum') { datasetCaudalSum = ds; } });
    var puntoActual = datasetCaudalSum ? puntoMasCercano(datasetCaudalSum.puntos, tsObjetivo, 30 * 60 * 1000) : null;
    $actual.html(puntoActual
        ? 'Valor actual de Caudal: <b>' + fmt(puntoActual.y) + ' L/s</b>'
        : '<span style="color:#d32f2f;">"Caudal" no tiene dato en esa hora exacta.</span>');
    $input.trigger('focus');
    function cerrar() { $overlay.remove(); }
    $overlay.find('.cd-modal-btn-cancelar').on('click', cerrar);
    $overlay.on('mousedown', function (evt) { if (evt.target === this) cerrar(); });
    $overlay.find('.cd-modal-btn-guardar').on('click', function () {
        var nuevoValor = parseFloat($input.val());
        if (isNaN(nuevoValor)) { $input.css('border-color', '#d32f2f'); return; }
        if (!puntoActual) { alert('No se puede corregir: "Caudal" no tiene ningún dato cerca de esa hora.'); return; }
        var $btn = $(this).prop('disabled', true).text('Guardando...');
        $nota.html('Recalculando y guardando ' + fechaStrCargada + '... esto reescribe "Caudal", "Caudal Medio" y el volumen del día.');
        corregirPicoCaudalSumDiaPasado($ctx, {
            grupoRef: estadoCrudo.entityRefBase,
            inicioTs: estadoCrudo.inicioDia,
            finTs: estadoCrudo.finDia - 1,
            tsObjetivo: puntoActual.x,
            nuevoValor: nuevoValor
        }).then(function (corregido) {
            log('[corregir pico] guardado correctamente: Caudal -> ' + nuevoValor + ' L/s en ' + new Date(puntoActual.x).toString());
            // Registro para la Auditoría: SOLO el punto corregido (aunque el
            // día entero se haya reescrito), con su valor anterior y el nuevo.
            if (corregido) {
                registrarCambio($ctx, estadoCrudo.entityRefBase.type, estadoCrudo.entityRefBase.id, [
                    { tipo: 'punto', clave: 'caudal_Sum', ts: corregido.ts, anterior: corregido.anterior, nuevo: corregido.nuevo }
                ]);
            }
            ajustesVolumenDia = { clave: null, cargando: false, mapa: {} }; // se vuelven a leer con el ajuste nuevo
            cerrar();
            // Se vuelve a pedir el día de verdad al servidor, igual que
            // tras guardar un cambio de signo.
            fetchManualYPintar(estadoCrudo.inicioDia, estadoCrudo.finDia - 1);
            try {
                window.dispatchEvent(new CustomEvent('riego-correccion-guardada', {
                    detail: { grupoId: estadoCrudo.entityRefBase.id, fechaStr: fechaStrCargada }
                }));
            } catch (e) {
                logError('[corregir pico] no se pudo lanzar el evento riego-correccion-guardada:', e);
            }
        }).catch(function (err) {
            logError('[corregir pico] fallo al guardar:', err);
            $btn.prop('disabled', false).text('Guardar');
            alert('No se pudo guardar la corrección: ' + (err && err.message ? err.message : 'error desconocido') + '\nVuelve a intentarlo.');
        });
    });
}

function guardarCambiosDeSigno($ctx) {
    if (guardando || !estadoCrudo) return;
    var idsCambiados = Object.keys(signosDia).filter(function (id) { return signosDia[id] !== signosOriginales[id]; });
    if (idsCambiados.length === 0) return;
    guardando = true;
    var $btn = $ctx.$container.find('.cd-btn-guardar').prop('disabled', true).text('Guardando...');
    var fechaStr = fechaStrCargada;
    var inicioTs = estadoCrudo.inicioDia;
    var finTs = estadoCrudo.finDia - 1;
    var cadena = Promise.resolve();
    idsCambiados.forEach(function (entityId) {
        var info = estadoCrudo.entidades[entityId];
        cadena = cadena.then(function () {
            return recalcularYGuardarDiaCorregido($ctx, {
                grupoRef: estadoCrudo.entityRefBase,
                caudalimetroRef: info.entityRef,
                caudalimetroNombre: info.nombre,
                inicioTs: inicioTs,
                finTs: finTs,
                fechaStr: fechaStr,
                signoAntiguo: (signosOriginales[entityId] === 'resta') ? -1 : 1,
                signoNuevo: (signosDia[entityId] === 'resta') ? -1 : 1
            });
        });
    });
    cadena.then(function () {
        log('[guardar] cambios de signo guardados correctamente para ' + fechaStr);
        signosOriginales = JSON.parse(JSON.stringify(signosDia));
        guardando = false;
        $btn.prop('disabled', false).text('Guardar cambios');
        pintarAvisoGuardar($ctx);
        // Se vuelve a pedir el dia de verdad al servidor, para reemplazar
        // la vista previa por los valores YA persistidos (deberian
        // coincidir, esto es solo para confirmar visualmente que ha
        // quedado guardado de verdad).
        fetchManualYPintar(inicioTs, finTs);
        // Aviso al resto de widgets del dashboard (Calendario, Resumen
        // Mensual, etc.) de que se ha corregido un dia -- igual que ya
        // hace el widget de Caudal Manual con "riego-caudal-manual-guardado".
        // El Calendario NO pide los datos por suscripcion en vivo (los pide
        // una vez por HTTP), asi que sin este aviso una correccion de un
        // dia pasado se queda invisible ahi hasta recargar toda la pagina.
        try {
            // LOG TEMPORAL DE DIAGNOSTICO -- se puede quitar una vez
            // confirmado que el Calendario recibe y procesa bien el aviso.
            console.warn('[DIAGNOSTICO] Lanzando riego-correccion-guardada con detail =', {
                grupoId: estadoCrudo.entityRefBase.id,
                fechaStr: fechaStr
            });
            window.dispatchEvent(new CustomEvent('riego-correccion-guardada', {
                detail: {
                    grupoId: estadoCrudo.entityRefBase.id,
                    fechaStr: fechaStr
                }
            }));
        } catch (e) {
            logError('[guardar] no se pudo lanzar el evento riego-correccion-guardada:', e);
        }
    }).catch(function (err) {
        logError('[guardar] fallo al guardar los cambios de signo:', err);
        guardando = false;
        $btn.prop('disabled', false).text('Guardar cambios');
        alert('No se pudieron guardar los cambios: ' + (err && err.message ? err.message : 'error desconocido') + '\nVuelve a intentarlo.');
    });
}

// Dibuja, al final de la linea de "Caudal Medio", la etiqueta numerica
// (entero, con unidad "L/s") del ultimo valor, justo encima del trazo.
function dibujarEtiquetaCaudalMedio(svg, crearEl, puntos, color) {
    if (!puntos || puntos.length === 0) return;
    var ultimo = puntos[puntos.length - 1];
    var texto = crearEl('text', {
        x: ultimo.xPix + 6, y: ultimo.yPix - 6,
        'font-size': 11, 'font-family': 'Roboto, sans-serif',
        'font-weight': 700, fill: color, 'text-anchor': 'start'
    });
    texto.textContent = fmt(ultimo.y) + ' L/s';
    svg.appendChild(texto);
}
// Dibuja una pequeña marca vertical ("guioncito") en cada punto donde ha
// habido una lectura real, permanente (no solo al pasar el ratón) -- así
// se ve de un vistazo dónde hay dato real y dónde la línea solo interpola
// entre dos lecturas. El círculo más grande que aparece al pasar el ratón
// por encima (ver hoverGroup) sigue funcionando igual, por encima de esto.
function dibujarMarcasDePunto(svg, crearEl, puntosPix, color, opacidad) {
    if (!puntosPix) return;
    puntosPix.forEach(function(p) {
        svg.appendChild(crearEl('line', {
            x1: p.xPix, y1: p.yPix - 3, x2: p.xPix, y2: p.yPix + 3,
            stroke: color, 'stroke-width': 1.5,
            opacity: opacidad !== undefined ? opacidad : 1
        }));
    });
}
// ============================================================
// Grafico SVG a mano: eje X fijo con las 24 horas del dia que se
// esta viendo, eje Y con escala redonda. Sin clic (no editable).
// ============================================================
function dibujarGrafico($ctx, datasets) {
    var $panel = $ctx.$container.find('.cd-chart-panel');
    var svg = $ctx.$container.find('#cd-svg')[0];
    if (!svg) { logWarn('dibujarGrafico() -- no se encontro #cd-svg, se aborta.'); return; }
    var ancho = $panel.width();
    var alto = $panel.height();
    if (ancho <= 0 || alto <= 0) { logWarn('dibujarGrafico() -- panel con tamaño 0 (ancho=' + ancho + ', alto=' + alto + '), se aborta.'); return; }
    while (svg.firstChild) { svg.removeChild(svg.firstChild); }
    svg.setAttribute('viewBox', '0 0 ' + ancho + ' ' + alto);
    var anchoPlot = ancho - MARGEN.left - MARGEN.right;
    var altoPlot = alto - MARGEN.top - MARGEN.bottom;
    if (anchoPlot <= 0 || altoPlot <= 0) return;
    var datasetsVisibles = datasets.filter(function(ds) { return !seriesOcultas[ds.id]; });
    var fechaRef = new Date();
    var fuenteDiaGrafico = leerDiaDesdeFuenteMasFiable();
    if (fuenteDiaGrafico) {
        fechaRef = new Date(fuenteDiaGrafico.ts);
    } else {
        var tsReferencia = null;
        datasetsVisibles.forEach(function(ds) {
            ds.puntos.forEach(function(p) {
                if (!isNaN(p.y) && (tsReferencia === null || p.x > tsReferencia)) { tsReferencia = p.x; }
            });
        });
        if (tsReferencia !== null) { fechaRef = new Date(tsReferencia); }
