    log('dibujarGrafico() -- dia mostrado: ' + new Date(inicioDia).toDateString() + ' -- series visibles: ' + datasetsVisibles.map(function(d) { return d.id; }).join(', '));
    // --- Dominio Y (ahora puede haber valores negativos por una linea de
    // caudalimetro puesta en "Resta") ---
    var yMin = Infinity, yMax = -Infinity;
    datasetsVisibles.forEach(function(ds) {
        ds.puntos.forEach(function(p) {
            if (p.x < inicioDia || p.x >= finDia) return;
            if (isNaN(p.y)) return;
