    if (yMin === yMax) { yMin -= 1; yMax += 1; }
    var escalaMax = calcularEscalaRedonda(0, Math.max(0, yMax), 5);
    var yMaxFinal = escalaMax.max;
    var yMinFinal = 0;
    if (yMin < 0) {
        var escalaMin = calcularEscalaRedonda(0, Math.abs(yMin), 5);
        yMinFinal = -escalaMin.max;
    }
    yMin = yMinFinal;
    yMax = yMaxFinal;
    function xPix(ts) { return MARGEN.left + ((ts - inicioDia) / (finDia - inicioDia)) * anchoPlot; }
    function yPix(v) { return MARGEN.top + (1 - (v - yMin) / (yMax - yMin)) * altoPlot; }
    function crearEl(tag, attrs) {
