        if (esMedia) { attrsLinea['stroke-dasharray'] = '7,5'; }
        svg.appendChild(crearEl('polyline', attrsLinea));
        var puntosRealesPix = puntosReales.map(function(p) { return { xPix: xPix(p.x), yPix: yPix(p.y) }; });
        dibujarMarcasDePunto(svg, crearEl, puntosRealesPix, ds.color);
        if (esMedia) {
            var puntosConPixeles = puntosValidos.map(function(p) { return { y: p.y, xPix: xPix(p.x), yPix: yPix(p.y) }; });
