        var top = evt.offsetY + 12;
        if (left + anchoTooltip > ancho) { left = evt.offsetX - anchoTooltip - 12; }
        if (top + altoTooltip > alto) { top = evt.offsetY - altoTooltip - 12; }
        if (left < 0) { left = 4; }
        if (top < 0) { top = 4; }
