        });
    }
}
// Calcula un rango [min, max] y una lista de "ticks" en numeros redondos.
function calcularEscalaRedonda(minDato, maxDato, maxTicksAprox) {
    function numeroRedondo(rango, redondear) {
        var exponente = Math.floor(Math.log10(rango));
        var fraccion = rango / Math.pow(10, exponente);
        var fraccionRedonda;
        if (redondear) {
            if (fraccion < 1.5) fraccionRedonda = 1;
            else if (fraccion < 3) fraccionRedonda = 2;
            else if (fraccion < 7) fraccionRedonda = 5;
            else fraccionRedonda = 10;
        } else {
            if (fraccion <= 1) fraccionRedonda = 1;
            else if (fraccion <= 2) fraccionRedonda = 2;
            else if (fraccion <= 5) fraccionRedonda = 5;
            else fraccionRedonda = 10;
        }
        return fraccionRedonda * Math.pow(10, exponente);
    }
    var rango = numeroRedondo(maxDato - minDato || 1, false);
    var paso = numeroRedondo(rango / (maxTicksAprox - 1), true);
    var min = Math.floor(minDato / paso) * paso;
    var max = Math.ceil(maxDato / paso) * paso;
    var ticks = [];
    for (var v = min; v <= max + paso * 0.001; v += paso) {
        ticks.push(Math.round(v * 1000) / 1000);
    }
    return { min: min, max: max, step: paso, ticks: ticks };
}
